"""Freeze source coverage, C root split and equal training budgets before any query optimization."""
from config import *
import collections
def main():
 states=read(REP/'data/public/states.json');labels=read(REP/'data/_private/labels.json');pairs=read(REP/'data/public/pairs.json');outcomes=read(REP/'data/_private/outcomes.json');budget=read(OLD/'configs/semantic_budget.json');original=budget['train_state_indices'];assert len(original)==144
 train_candidates=[i for i,s in enumerate(states)if s['split']=='train'and str(i)in labels]
 heldopen=[i for i in train_candidates if all(labels[str(i)]['v'][:3])and any(labels[str(i)]['y'][:3])and all(labels[str(i)]['v'][6:])and labels[str(i)]['y'][7]]
 heldclosed=[i for i in train_candidates if all(labels[str(i)]['v'][:3])and any(labels[str(i)]['y'][:3])and all(labels[str(i)]['v'][6:])and labels[str(i)]['y'][6]]
 postplace=sorted({p['after']for p in pairs if p['split']=='train'and p['skill']=='place_in_drawer'and outcomes[p['id']]['status']=='success'and str(p['after'])in labels})
 targets={'holding_open':heldopen,'post_place':postplace,'holding_closed':heldclosed};target_set=set(sum(targets.values(),[]));added=sorted(target_set-set(original));assert len(added)==16 and len(heldclosed)==8
 disposable=[i for i in original if i not in target_set];drop=sorted(disposable,key=lambda i:hashlib.sha256(f'headcoverage20261016:{states[i]["root_id"]}:{i}'.encode()).hexdigest())[:len(added)];shared=sorted(set(original)-set(drop));pools={'original_coverage':sorted(original),'intermediate_coverage':sorted(set(shared)|set(added))};assert len(shared)==128 and all(len(x)==144 for x in pools.values())
 csel=['C_semantics_v2_chain_blue_0']+[f'C_semantics_v2_fixtures_{c}_0'for c in['red','blue','pink']]+['C_statedep_place_blue_0']
 crows=[i for i,s in enumerate(states)if s['split']=='dev'and str(i)in labels];croots=sorted({states[i]['root_id']for i in crows});cval=sorted(set(croots)-set(csel));assert len(csel)==5 and len(cval)==6
 cselection=[i for i in crows if states[i]['root_id']in csel];cvalidation=[i for i in crows if states[i]['root_id']in cval]
 for arm,ix in pools.items():assert all(states[i]['root_id'].startswith(('A_','B_'))and states[i]['split']=='train'for i in ix)
 assert not(set(csel)&set(cval))
 # Exact public-content overlap check across AB, C-selection and C-validation.
 groups={'AB':set(sum(pools.values(),[])),'C_selection':set(cselection),'C_validation':set(cvalidation)};content={}
 for group,ix in groups.items():
  for i in ix:
   h=states[i].get('content_sha256')or content_hash(states[i]['path']);content.setdefault(h,set()).add(group)
 assert all(len(x)==1 for x in content.values()),'Identical public observation crosses query splits'
 query_result=read(OLD/'results/query_interaction_seed0.json');weights=query_result['class_weights']
 protocol={'frozen_utc':now(),'scope':'Only retrain original25473-parameter Query MLP. Same canonical_matched world-model seed0/update1000 frozen for all runs; seeds0/1 below are QUERY initialization and sampler seeds, not two encoders. No dynamics/encoder/planner training, simulation, new evaluation collection, packages or threshold changes.','arms':list(pools),'query_seeds':[0,1],'initialization':'Fresh original Query class, torch seed3000+query_seed, identical state within paired arms. No extra capacity.','normalization':'Original query_seed0 normalization reused exactly, fitted previously on AB representation states; no recomputation from C/D or added states.','updates_per_run':1200,'batch_size':32,'sample_draws_per_run':38400,'distinct_training_states_per_arm':144,'shared_training_states':128,'replacement_states':16,'base_draws_per_update':20,'aux_draws_per_update':12,'control_aux':'12 root-balanced draws from original144-state pool.','coverage_aux':'4 root-balanced draws each from holding_open, post_place, holding_closed strata.','shared_base':'Exactly same20 state IDs per update across arms, from common128 states, root-balanced.','optimizer':{'type':'AdamW','lr':.001,'weight_decay':.001,'gradient_clip_norm':1},'loss':'Same original masked average of Holding BCE, In BCE and drawer3-class CE; validity masks preserved. Both arms use same fixed weights computed from original144 labels, not arm-dependent weights.','class_weights':weights,'checkpoints':[300,600,900,1200],'selection':'Minimum C-selection root-macro masked query loss; earlier tie. All1200 updates run. C-validation not loaded for selection.','thresholds':'Holding/In probability>=0.5, drawer argmax; unchanged.','C_selection_roots':csel,'C_validation_roots':cval,'C_split_rule':'Public root-name rule fixed before new training: blue chain, rep0 fixtures in each colour, blue matched root for selection; remaining C roots held out for query validation.','known_history':'C was used in earlier representation experiments; current query selection/validation roots are disjoint but this is not a brand-new unseen world-model generalization test. D/D2 have been inspected repeatedly and are diagnostic backtests only.','source_labels':'Existing frozen v2.1 labels, no new labels inferred. Extra matched states have6 valid Holding/drawer facts and3 unknown In facts due missing orientations. Unknown never becomesfalse.','partial_coverage_limit':'AB held_closed8 states/4roots; C held_closed4 states/2roots, one root2states in selection and one root2states in validation. Cannot establish complete9-fact held_closed readability or robust cross-root generalization from this data.','allowed_training_data':'AB true observation encodings only. No predicted-state labels, D, D2, the5 normal diagnostic roots, or recorded test streams in training/selection.','one_shot':'One predefined pair of coverage arms x2 seeds, no iterative repairs or validation-driven changes.'}
 selection={'pools':pools,'shared':shared,'added':added,'dropped':drop,'targets':targets,'C_selection_indices':cselection,'C_validation_indices':cvalidation}
 save(E/'configs/head_protocol.json',protocol);save(E/'configs/head_selection.json',selection)
 def info(ix):
  return {'states':len(ix),'roots':sorted({states[i]['root_id']for i in ix}),'full9_states':sum(all(labels[str(i)]['v'])for i in ix),'validity_counts':dict(collections.Counter(sum(labels[str(i)]['v'])for i in ix))}
 save(E/'results/head_data_coverage.json',{'arms':{a:info(ix)for a,ix in pools.items()},'aux_strata':{a:info(ix)for a,ix in targets.items()},'C_selection':info(cselection),'C_validation':info(cvalidation),'exact_public_content_split_overlap':0})
 def sample(rng,ix,n):
  roots=sorted({states[i]['root_id']for i in ix});groups=[[i for i in ix if states[i]['root_id']==root]for root in roots];return [groups[j][rng.integers(len(groups[j]))]for j in rng.integers(len(groups),size=n)]
 for seed in[0,1]:
  rng=np.random.default_rng(6000+seed);base=np.array([sample(rng,shared,20)for _ in range(1200)]);control=np.array([sample(rng,pools['original_coverage'],12)for _ in range(1200)]);coverage=np.array([sum([sample(rng,targets[k],4)for k in ['holding_open','post_place','holding_closed']],[])for _ in range(1200)])
  for arm,aux in [('original_coverage',control),('intermediate_coverage',coverage)]:
   mapping={i:j for j,i in enumerate(pools[arm])};global_ids=np.concatenate([base,aux],1);local=np.array([[mapping[int(i)]for i in row]for row in global_ids]);np.savez_compressed(E/'configs'/f'head_schedule_{arm}_seed{seed}.npz',indices=local,state_ids=global_ids)
 sources=[REP/'data/public/states.json',REP/'data/public/pairs.json',REP/'data/public/inputs.npz',REP/'data/_private/labels.json',REP/'data/_private/outcomes.json',REP/'data/public/normalization.npz',REP/'models/query_seed0.pt',OLD/'configs/semantic_budget.json',OLD/'results/query_interaction_seed0.json',REP/'models/canonical_matched_seed0/selected.json',REP/'models/canonical_matched_seed0/update1000.pt']
 save(E/'configs/head_source_hashes.json',{'sha256':{str(p):sha(p)for p in sources}});print('HEAD_PROTOCOL_FROZEN',json.dumps(read(E/'results/head_data_coverage.json'),ensure_ascii=False),flush=True)
if __name__=='__main__':main()
